import { NavLink, Outlet, useNavigate } from "react-router-dom";

const menuItems = [
  { to: "/professional/dashboard", label: "Dashboard", icon: "⊞", end: true },
  { to: "/professional/dashboard/announcements", label: "Announcements", icon: "≡" },
  { to: "/professional/dashboard/profile", label: "My Profile", icon: "◎" },
];

const accountItems = [
  { to: "/professional/dashboard/settings", label: "Settings", icon: "⚙" },
];

export default function ProfessionalDashboardLayout() {
  const navigate = useNavigate();

  const navItem = (item) => (
    <NavLink
      key={item.to}
      to={item.to}
      end={item.end}
      className={({ isActive }) =>
        `flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm transition-all
        ${isActive
          ? "bg-pro-blue text-navy font-medium"
          : "text-gray-500 hover:bg-cream hover:text-gray-900"}`
      }
    >
      <span className="w-4 text-center text-base">{item.icon}</span>
      {item.label}
    </NavLink>
  );

  return (
    <div className="flex min-h-screen bg-cream font-sans">
      <aside className="w-60 bg-white border-r border-gray-100 fixed top-0 left-0 bottom-0 flex flex-col px-4 py-5 overflow-y-auto z-10">
        <div
          className="flex items-center gap-2 px-2 mb-6 cursor-pointer"
          onClick={() => navigate("/")}
        >
          <div className="w-8 h-8 bg-navy rounded-lg flex items-center justify-center text-white font-bold text-sm">
            A
          </div>
          <span className="font-semibold text-gray-900">WorkBridge DZ</span>
        </div>

        <p className="text-[10px] tracking-widest text-gray-300 px-2 mb-2">MENU</p>
        <nav className="flex flex-col gap-1 mb-4">{menuItems.map(navItem)}</nav>

        <p className="text-[10px] tracking-widest text-gray-300 px-2 mb-2">ACCOUNT</p>
        <nav className="flex flex-col gap-1">{accountItems.map(navItem)}</nav>

        <div className="mt-auto flex items-center gap-3 bg-gray-50 rounded-xl p-3">
          <div className="w-9 h-9 bg-pro-blue rounded-full flex items-center justify-center text-navy text-xs font-semibold">
            YB
          </div>
          <div>
            <p className="text-sm font-medium text-gray-900">Yacine Benali</p>
            <p className="text-xs text-gray-400">Professional</p>
          </div>
        </div>
      </aside>

      <div className="ml-60 flex-1 flex flex-col min-h-screen">
        <div className="h-14 bg-cream border-b border-gray-100 flex items-center justify-end px-8">
          <span className="text-sm text-gray-400">Professional Portal</span>
        </div>
        <div className="p-8 flex-1">
          <Outlet />
        </div>
      </div>
    </div>
  );
}
